{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "How should travel time between two locations be computed from the given coordinates — is it Euclidean distance (in the same units as the objective, with travel time equal to that distance in minutes), or Manhattan distance, or some other metric?"
  ],
  "rationale": "The response asks for a single policy choice regarding the distance metric to use for travel time calculation."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do all trucks start at the depot at time 0 and must they return to the depot after finishing their route, or is returning to the depot optional?"
  ],
  "rationale": "The response asks a single clarification question regarding truck start and end conditions, presented as one policy choice."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a maximum route duration or latest return time that each truck must respect (for example, all trucks must be back at the depot by 1236 minutes), or is the only time restriction the customer time windows?"
  ],
  "rationale": "The response asks a single clarification question about whether there is a maximum route duration or latest return time, or if only customer time windows apply."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Does the depot's operating time window [0, 1236] mean every truck must depart at or after time 0 and return to the depot at or before time 1236, or is the depot window just informational and trucks may return after 1236?"
  ],
  "rationale": "The response asks for a single policy clarification regarding the interpretation of the depot time window constraints."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "is the waiting time counted as part of the route's timeline (i.e., the truck is occupied and cannot serve another customer while waiting)",
    "does waiting affect anything else such as the objective or any limit?"
  ],
  "rationale": "The response asks two distinct questions: one about whether waiting time occupies the truck's timeline, and another about whether waiting impacts the objective or other limits."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a single truck visit the same customer more than once, or must each customer be served exactly once by exactly one truck?"
  ],
  "rationale": "The response asks for a single policy choice regarding visit frequency and service exclusivity, which constitutes one independent clarification question."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "Are all 5 trucks available and identical (same capacity 200, same depot start/end)?",
    "Is it acceptable to use fewer than 5 trucks if that minimizes total distance?"
  ],
  "rationale": "The response contains two semantically independent questions: one regarding the availability and uniformity of the trucks, and another regarding the policy on using a subset of the fleet."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The objective is to minimize total distance traveled by all vehicles — does this include the distance from the depot to the first customer and from the last customer back to the depot, or only the distances between customers?"
  ],
  "rationale": "The response asks a single clarification question regarding the scope of the distance metric (depot-to-customer vs. customer-to-customer only)."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the distance metric for the objective the same Euclidean distance used for travel time, so that the objective is the sum of Euclidean distances over all arcs (depot-to-first, between customers, last-to-depot)?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of the distance metric used in the objective function."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any restriction on the number of customers a single truck can serve on one route (other than the 200-unit capacity limit), or can a truck serve as many customers as it can fit within capacity and the time windows?"
  ],
  "rationale": "The response asks a single clarification question regarding whether there is a limit on the number of customers per truck, distinct from the capacity limit."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a truck departs the depot, does it carry the full load for all customers on its route (so the capacity constraint is the sum of demands on the route ≤ 200), or does it pick up/drop off along the way such that capacity is checked differently?"
  ],
  "rationale": "The response asks a single clarification question regarding the capacity constraint logic, presenting two mutually exclusive options for the same policy decision."
}

{
  "action": "question",
  "question_count": 1,
